#Requires -Version 5.1
# fix-partes-upload-definitivo.ps1
# Dos bugs en el upload de documentos:
#
# BUG 1 - Elimina la obra al subir:
#   handleUploadFile tenia un bloque "Save form first" que actualizaba el parte
#   antes de subir el archivo. Si form.obra_id era distinto a parte.obra_id
#   (por un re-render en movil) guardaba obra_id=null sobreescribiendo la obra.
#   FIX: eliminado ese bloque completamente. El upload no debe guardar el form.
#
# BUG 2 - Parece que sube pero no aparece:
#   Despues de subir llamaba a fetchData() que recarga TODO el formulario
#   desde Supabase, sobreescribiendo los cambios que el usuario estaba editando.
#   FIX: en lugar de fetchData(), recarga solo la lista de documentos.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null

$File = Join-Path $RepoPath "src\app\partes\[id]\page.tsx"
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes($File, $bytes)

$c = [System.IO.File]::ReadAllText($File, [System.Text.Encoding]::UTF8)
$ok1 = -not $c.Contains("Save form first")
$ok2 = $c.Contains("Recargar solo documentos")
$ok3 = $c.Contains('opacity: 0')
if ($ok1) { Write-Host "  OK: bloque Save form eliminado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($ok2) { Write-Host "  OK: fetchData parcial (solo docs)" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($ok3) { Write-Host "  OK: input con opacity:0 (Android)" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host '  git add "src\app\partes\[id]\page.tsx"'
Write-Host '  git commit -m "fix: upload docs - quitar Save form first + fetchData parcial"'
Write-Host '  git push'
